#include <Processing.NDI.Lib.h>
#include <chrono>
#include <iostream>
#include <string>
#include <thread>
#include <vector>
static std::vector<NDIlib_source_t> find_sources(NDIlib_find_instance_t f){NDIlib_find_wait_for_sources(f,1500);uint32_t n=0;auto p=NDIlib_find_get_current_sources(f,&n);return p?std::vector<NDIlib_source_t>(p,p+n):std::vector<NDIlib_source_t>();}
static NDIlib_recv_instance_t connect_source(const std::string& name){auto f=NDIlib_find_create_v2();if(!f)return nullptr;auto sources=find_sources(f);NDIlib_recv_instance_t r=nullptr;for(auto&s:sources)if(s.p_ndi_name&&name==s.p_ndi_name){NDIlib_recv_create_v3_t c{};c.source_to_connect_to=s;c.color_format=NDIlib_recv_color_format_fastest;c.bandwidth=NDIlib_recv_bandwidth_metadata_only;c.allow_video_fields=true;c.p_ndi_recv_name="PTZ Control Web";r=NDIlib_recv_create_v3(&c);break;}NDIlib_find_destroy(f);if(r)std::this_thread::sleep_for(std::chrono::milliseconds(900));return r;}
int main(int argc,char**argv){if(!NDIlib_initialize()){std::cerr<<"NDI Runtime could not initialize";return 2;}if(argc==2&&std::string(argv[1])=="list"){auto f=NDIlib_find_create_v2();if(!f)return 3;auto s=find_sources(f);std::cout<<"[";for(size_t i=0;i<s.size();++i){if(i)std::cout<<",";std::string n=s[i].p_ndi_name?s[i].p_ndi_name:"";std::cout<<"\"";for(char c:n){if(c=='\"'||c=='\\')std::cout<<'\\';std::cout<<c;}std::cout<<"\"";}std::cout<<"]";NDIlib_find_destroy(f);NDIlib_destroy();return 0;}if(argc<5||std::string(argv[1])!="control"){std::cerr<<"usage: ndi-ptz-bridge list | control <source> <command> [args]";return 4;}auto r=connect_source(argv[2]);if(!r){std::cerr<<"NDI source not found: "<<argv[2];return 5;}std::string c=argv[3];bool ok=false;if(c=="move"&&argc>=6)ok=NDIlib_recv_ptz_pan_tilt_speed(r,std::stof(argv[4]),std::stof(argv[5]));else if(c=="zoom")ok=NDIlib_recv_ptz_zoom_speed(r,std::stof(argv[4]));else if(c=="autofocus")ok=NDIlib_recv_ptz_auto_focus(r);else if(c=="focus")ok=NDIlib_recv_ptz_focus_speed(r,std::stof(argv[4]));else if(c=="recall")ok=NDIlib_recv_ptz_recall_preset(r,std::stoi(argv[4]),1.0f);else if(c=="save")ok=NDIlib_recv_ptz_store_preset(r,std::stoi(argv[4]));else if(c=="home")ok=NDIlib_recv_ptz_pan_tilt(r,0.0f,0.0f);NDIlib_recv_destroy(r);NDIlib_destroy();if(!ok){std::cerr<<"NDI PTZ command rejected or unsupported";return 6;}return 0;}